# >>>GEN A2_FILE_REVERSALS


def has_layer(src: str) -> bool:
    return MARKER in src


def peel(src: str) -> str:
    """undo the A2 edits (each `new` text must occur exactly once); a trainer without the layer is returned unchanged"""
    if not has_layer(src):
        return src
    for new, old in A2_FILE_REVERSALS:
        assert src.count(new) == 1, f"A2 reversal: the text occurs {src.count(new)} times (must be exactly 1): {new[:70]!r}"
        src = src.replace(new, old)
    return src
